import sys

MOD = 1000000007
SIZE = 250

def poly_mult(u, v, reductions):
    z = [0] * (2 * SIZE - 1)

    if u is v:
        for i in range(SIZE):
            x = u[i]
            if x == 0:
                continue
            z[i + i] += x * x
            for j in range(i + 1, SIZE):
                y = u[j]
                if y:
                    z[i + j] += 2 * x * y
    else:
        for i in range(SIZE):
            x = u[i]
            if x == 0:
                continue
            for j in range(SIZE):
                y = v[j]
                if y:
                    z[i + j] += x * y

    for i in range(2 * SIZE - 1):
        z[i] %= MOD

    for i in range(2 * SIZE - 2, SIZE - 1, -1):
        value = z[i]
        if value:
            for d in reductions:
                index = i - d
                z[index] += value
                if z[index] >= MOD:
                    z[index] -= MOD

    return z[:SIZE]

def poly_pow(base, exponent, reductions):
    result = [0] * SIZE
    result[0] = 1

    while exponent:
        if exponent & 1:
            result = poly_mult(result, base, reductions)
        exponent >>= 1
        if exponent:
            base = poly_mult(base, base, reductions)

    return result

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    iterator = iter(data)

    n = next(iterator)
    m = next(iterator)
    k = next(iterator)

    a = [next(iterator) for _ in range(n)]
    b = [next(iterator) for _ in range(m)]

    total = [0] * SIZE

    if a:
        powers = []
        x = [0] * SIZE
        x[1] = 1
        powers.append(x)

        for _ in range(1, max(a).bit_length()):
            powers.append(poly_mult(powers[-1], powers[-1], b))

        for exponent in a:
            current = [0] * SIZE
            current[0] = 1
            bit = 0

            while exponent:
                if exponent & 1:
                    current = poly_mult(current, powers[bit], b)
                exponent >>= 1
                bit += 1

            for i in range(SIZE):
                total[i] += current[i]
                if total[i] >= MOD:
                    total[i] -= MOD

    total = poly_pow(total, k, b)

    for i in range(SIZE - 1, 0, -1):
        value = total[i]
        if value:
            for d in b:
                if i >= d:
                    total[i - d] += value
                    if total[i - d] >= MOD:
                        total[i - d] -= MOD

    print(total[0])

if __name__ == "__main__":
    main()

